from pathlib import Path
import hashlib
p=Path('cloudflare-worker/hyro-execution.js')
s=p.read_text()
raw=s.encode(); blob=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()
expected='b97695c3f96939290e4a80d24d9fc702d154b29a'
assert blob==expected,(blob,expected)
old='import {hmacHex} from "./providers/bybit-signed-client.js";\n'
new='''import {hmacHex} from "./providers/bybit-signed-client.js";\n\nasync function sha256Hex(input){\n  const data=new TextEncoder().encode(String(input));\n  const digest=await crypto.subtle.digest("SHA-256",data);\n  return Array.from(new Uint8Array(digest)).map(b=>b.toString(16).padStart(2,"0")).join("");\n}\n'''
assert s.count(old)==1
s=s.replace(old,new,1)
old='const IDEMPOTENCY_PREFIX="v7718:hyro:intent:";\n'
new='const IDEMPOTENCY_PREFIX="v7718:hyro:intent:";\nconst RETRYABLE_REJECTION_CODES=new Set([10001,110007,110012,110017,110032,110044,110045]);\n'
assert s.count(old)==1
s=s.replace(old,new,1)
old='''async function appendHistory(env,event){const h=await kvGet(env,EXEC_HISTORY_KEY,[]);await kvPut(env,EXEC_HISTORY_KEY,[event,...(Array.isArray(h)?h:[])].slice(0,500));}\nexport async function executeHyroPlan(env,plan){const t=await getHyroTelemetry(env),gate=await evaluateHyroGate(env,plan,t);if(!gate.ok)return {ok:false,executed:false,gate};const key=String(plan.setupId||plan.id||`${gate.symbol}:${gate.side}:${gate.entry}`),idKey=IDEMPOTENCY_PREFIX+key,existing=await kvGet(env,idKey,null);if(existing)return {ok:true,executed:false,idempotent:true,existing};const order=await normalizedOrder(env,plan,gate),orderLinkId=`hyro-${Date.now().toString(36)}-${crypto.randomUUID().slice(0,8)}`,resp=await signedBybit(env,"POST","/v5/order/create",{...order,orderLinkId}),record={id:key,orderLinkId,orderId:resp?.result?.orderId||null,symbol:order.symbol,side:order.side,orderType:order.orderType,qty:order.qty,entry:gate.entry,sl:gate.sl,tp:gate.tp,rr:gate.rr,riskBudget:gate.riskBudget,riskMultiplier:gate.riskMultiplier,riskScale:gate.riskScale,capitalBasis:gate.dynamicRisk?.capitalBasis,riskPolicy:gate.dynamicRisk?.policy,mode:mode(env),createdAt:Date.now(),status:"SUBMITTED"};await kvPut(env,idKey,record,604800);await appendHistory(env,{type:"SUBMIT",...record});return {ok:true,executed:true,order:record,silentTelegram:true};}\n'''
new='''async function appendHistory(env,event){const h=await kvGet(env,EXEC_HISTORY_KEY,[]);await kvPut(env,EXEC_HISTORY_KEY,[event,...(Array.isArray(h)?h:[])].slice(0,500));}\n\nasync function findOrderByLinkId(env,symbol,orderLinkId){\n  let liveOk=false,histOk=false,liveError=null,histError=null;\n  try{\n    const live=await signedBybit(env,"GET","/v5/order/realtime",{category:"linear",symbol,orderLinkId});\n    liveOk=true;\n    const liveHit=live?.result?.list?.find(x=>x.orderLinkId===orderLinkId);\n    if(liveHit)return {found:true,orderId:liveHit.orderId,orderStatus:liveHit.orderStatus,source:"realtime"};\n  }catch(e){liveError=String(e?.message||e);}\n  try{\n    const hist=await signedBybit(env,"GET","/v5/order/history",{category:"linear",symbol,orderLinkId,limit:5});\n    histOk=true;\n    const histHit=hist?.result?.list?.find(x=>x.orderLinkId===orderLinkId);\n    if(histHit)return {found:true,orderId:histHit.orderId,orderStatus:histHit.orderStatus,source:"history"};\n  }catch(e){histError=String(e?.message||e);}\n  if(liveOk&&histOk)return {found:false};\n  return {found:null,error:[liveError&&`realtime: ${liveError}`,histError&&`history: ${histError}`].filter(Boolean).join(" | ")||"ORDER_LOOKUP_INCOMPLETE"};\n}\n\nasync function reconcileIntentByOrderLinkId(env,idKey,record){\n  const lookup=await findOrderByLinkId(env,record.symbol,record.orderLinkId);\n  if(lookup.found===true){\n    const acked={...record,state:"ACKNOWLEDGED",orderId:lookup.orderId,orderStatus:lookup.orderStatus,reconciledAt:Date.now()};\n    await kvPut(env,idKey,acked,604800);\n    await appendHistory(env,{type:"RECONCILE_FOUND",id:record.id,orderLinkId:record.orderLinkId,orderId:lookup.orderId,source:lookup.source,at:Date.now()});\n    return {ok:true,state:"ACKNOWLEDGED",record:acked};\n  }\n  if(lookup.found===false){\n    const failed={...record,state:"FAILED_RETRYABLE",reconciledAt:Date.now()};\n    await kvPut(env,idKey,failed,86400);\n    await appendHistory(env,{type:"RECONCILE_ABSENT",id:record.id,orderLinkId:record.orderLinkId,at:Date.now()});\n    return {ok:true,state:"FAILED_RETRYABLE",record:failed};\n  }\n  const pending={...record,state:"RECONCILE_REQUIRED",reconcileError:lookup.error||null,reconcileAttemptedAt:Date.now()};\n  await kvPut(env,idKey,pending,604800);\n  await appendHistory(env,{type:"RECONCILE_LOOKUP_FAILED",id:record.id,orderLinkId:record.orderLinkId,error:lookup.error,at:Date.now()});\n  return {ok:false,state:"RECONCILE_REQUIRED",record:pending,error:lookup.error};\n}\n\nexport async function executeHyroPlan(env,plan){\n  const planSymbol=String(plan?.symbol||"").toUpperCase(),planSide=sideOf(plan),planEntry=entryOf(plan),\n        key=String(plan.setupId||plan.id||`${planSymbol}:${planSide}:${planEntry}`),idKey=IDEMPOTENCY_PREFIX+key;\n  let existing=await kvGet(env,idKey,null);\n  if(existing){\n    const st=existing.state||"ACKNOWLEDGED";\n    if(st==="ACKNOWLEDGED")return {ok:true,executed:false,idempotent:true,existing};\n    if(st==="SUBMITTING"||st==="RECONCILE_REQUIRED"){\n      const r=await reconcileIntentByOrderLinkId(env,idKey,existing);\n      if(r.state==="ACKNOWLEDGED")return {ok:true,executed:false,idempotent:true,existing:r.record};\n      if(!r.ok)return {ok:false,executed:false,gate:{reason:"RECONCILE_REQUIRED",detail:r.error||null}};\n      existing=r.record;\n    }\n  }\n  const t=await getHyroTelemetry(env),gate=await evaluateHyroGate(env,plan,t);\n  if(!gate.ok)return {ok:false,executed:false,gate};\n  const accountId=String(env.HYRO_ACCOUNT_ID||"A"),scanId=String(plan.scanId||plan.lineage?.scanId||"unknown-scan"),\n        deterministicOrderLinkId="h"+(await sha256Hex(`${accountId}|${gate.symbol}|${gate.side}|${key}|${scanId}`)).slice(0,32),\n        orderLinkId=existing?.orderLinkId||deterministicOrderLinkId;\n  const order=await normalizedOrder(env,plan,gate);\n  const prepared={id:key,orderLinkId,symbol:order.symbol,side:order.side,orderType:order.orderType,qty:order.qty,entry:gate.entry,sl:gate.sl,tp:gate.tp,rr:gate.rr,riskBudget:gate.riskBudget,riskMultiplier:gate.riskMultiplier,riskScale:gate.riskScale,capitalBasis:gate.dynamicRisk?.capitalBasis,riskPolicy:gate.dynamicRisk?.policy,mode:mode(env),accountId,scanId,createdAt:existing?.createdAt||Date.now(),state:"PREPARED"};\n  await kvPut(env,idKey,prepared,604800);\n  const submitting={...prepared,state:"SUBMITTING",submittedAt:Date.now()};\n  await kvPut(env,idKey,submitting,604800);\n  let resp;\n  try{resp=await signedBybit(env,"POST","/v5/order/create",{...order,orderLinkId});}\n  catch(e){\n    const bybit=e?.bybit;\n    if(bybit&&Number.isFinite(bybit.retCode)&&RETRYABLE_REJECTION_CODES.has(bybit.retCode)){\n      const failed={...submitting,state:"FAILED_RETRYABLE",failReason:bybit.retMsg||String(e?.message||e),retCode:bybit.retCode,failedAt:Date.now()};\n      await kvPut(env,idKey,failed,86400);await appendHistory(env,{type:"SUBMIT_REJECTED",id:key,orderLinkId,retCode:bybit.retCode,retMsg:bybit.retMsg,at:Date.now()});\n      return {ok:false,executed:false,gate:{reason:"ORDER_REJECTED",retCode:bybit.retCode,retMsg:bybit.retMsg}};\n    }\n    const pending={...submitting,state:"RECONCILE_REQUIRED",ambiguousError:String(e?.message||e),ambiguousAt:Date.now()};\n    await kvPut(env,idKey,pending,604800);await appendHistory(env,{type:"SUBMIT_AMBIGUOUS",id:key,orderLinkId,error:String(e?.message||e),bybit:bybit||null,at:Date.now()});\n    return {ok:false,executed:false,gate:{reason:"RECONCILE_REQUIRED",detail:String(e?.message||e)}};\n  }\n  const orderId=resp?.result?.orderId||null;\n  if(!orderId){\n    const pending={...submitting,state:"RECONCILE_REQUIRED",ambiguousError:"ACK_WITHOUT_ORDER_ID",ambiguousAt:Date.now()};\n    await kvPut(env,idKey,pending,604800);await appendHistory(env,{type:"SUBMIT_AMBIGUOUS",id:key,orderLinkId,error:"ACK_WITHOUT_ORDER_ID",at:Date.now()});\n    return {ok:false,executed:false,gate:{reason:"RECONCILE_REQUIRED",detail:"ACK_WITHOUT_ORDER_ID"}};\n  }\n  const record={...submitting,state:"ACKNOWLEDGED",orderId,acknowledgedAt:Date.now(),status:"SUBMITTED"};\n  await kvPut(env,idKey,record,604800);await appendHistory(env,{type:"SUBMIT",...record});\n  return {ok:true,executed:true,order:record,silentTelegram:true};\n}\n'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,new,1)
assert 'crypto.randomUUID' not in s
p.write_text(s)
print('V78-026 H1 patch applied')
